from pathlib import Path
import json, math
ROOT=Path(__file__).resolve().parents[1]
def lua(o):
    if isinstance(o,dict):return '{'+','.join('['+json.dumps(str(k))+']='+lua(v) for k,v in o.items())+'}'
    if isinstance(o,list):return '{'+','.join(map(lua,o))+'}'
    if isinstance(o,bool):return 'true' if o else 'false'
    if o is None:return 'nil'
    return json.dumps(o)
data=json.loads((ROOT/'source_assets/layout.json').read_text())
data['protocol']='PSG/0.6.0'
data['quality']={'LOW':{'tier':'low','reflections':.25,'normal':0,'lightCount':2},'MEDIUM':{'tier':'medium','reflections':.6,'normal':.5,'lightCount':3},'HIGH':{'tier':'high','reflections':1,'normal':1,'lightCount':4}}
data['ropeLOD']={'HIGH':{'enter':24,'leave':32},'MEDIUM':{'enter':14,'leave':20},'LOW':{'enter':0,'leave':0}}
data['standing']={'tugLeft':[[x,0,1] for x in [-18.9,-17.3,-15.7]],'tugRight':[[x,0,1] for x in [18.9,17.3,15.7]],'bridgeStart':[46,-23,1]}
anchors=[]
for team,heading in [('left',270),('right',90)]:
    points=data['standing']['tugLeft' if team=='left' else 'tugRight']
    for i,p in enumerate(points):
        angle=math.radians(heading)
        palms=[[p[0]-math.sin(angle)*y,math.cos(angle)*y,1.05] for y in [.33,.47]]
        anchors.append({'id':f'TW_{team}_{i+1}','team':team,'source_rig_root':[p[0],0,0],'mta_spawn_reference':p,'rotation_z_degrees':heading,'palm_centres':palms,'scope':'Source-rig anchor only. Target GTA root offset and hand mesh/fingers require retarget validation.'})
data['animationAnchors']=anchors
zones=[{'id':a['id'],'kind':'tug_slot','anchor':a['id'],'position':a['mta_spawn_reference'],'radius':.85,'verticalTolerance':1.5,'exitRadius':1.25,'label':a['id'].replace('_',' ').upper(),'heading':a['rotation_z_degrees']} for a in anchors]
zones.extend([{'id':'GB_START','kind':'bridge_entry','position':[46,-23,1],'radius':1.4,'verticalTolerance':1.5,'exitRadius':2.2,'label':'GLASS BRIDGE / READY'}, {'id':'EXIT','kind':'exit','position':[0,-44,1],'radius':1.75,'verticalTolerance':1.5,'exitRadius':2.5,'label':'LEAVE COMPLEX'}])
data['interactionZones']=zones
data['interactionRequestInterval']=400
data['interactionKey']='e'
routes=[{'id':'ENTRY_LEFT','label':'ENTRY / TUG LEFT','points':[[x,y,.06] for x,y in [(0,-44),(0,-32),(-21,-32),(-21,-24),(-25.5,-24),(-25.5,-3),(-18.9,-3),(-18.9,0)]]}, {'id':'ENTRY_RIGHT','label':'ENTRY / TUG RIGHT','points':[[x,y,.06] for x,y in [(0,-44),(0,-32),(21,-32),(21,-24),(25.5,-24),(25.5,-3),(18.9,-3),(18.9,0)]]}, {'id':'ENTRY_GLASS','label':'ENTRY / GLASS START','points':[[x,y,.06] for x,y in [(0,-44),(0,-32),(46,-32),(46,-23)]]}]
data['inspectionRoutes']=routes

(ROOT/'source_assets/interactions.json').write_text(json.dumps({'protocol':data['protocol'],'zones':zones,'key':data['interactionKey'],'routes':routes,'scope':'Proximity / reservation scaffolding only; no rounds, forces, elimination or automatic animation playback'},indent=2))

(ROOT/'source_assets/animations/grip_alignment.json').write_text(json.dumps({'source_facing':'+Y','source_up':'+Z','anchors':anchors,'rope_on_platforms_z':1.05,'note':'Rig root != GTA ped collision origin; spawn reference is not a proven animation attachment.'},indent=2))
(ROOT/'shared/config.lua').write_text('-- Generated by tools/build_runtime.py. World = origin + local metres.\nPSG_CONFIG='+lua(data)+'\n')
for name,porosity,metal,rough,glass in [('concrete',.75,0,.85,0),('metal',.08,.8,.5,0),('glass',0,0,.12,1),('asphalt',.9,0,.92,0),('floor',.15,.6,.5,0),('rope',.65,0,.98,0)]:
    (ROOT/f'shaders/{name}.fx').write_text(f'#define POROSITY {porosity}\n#define METAL {metal}\n#define ROUGH {rough}\n#define GLASS {glass}\n#include "surface.fxh"\n')
files=['shared/config.lua','server/main.lua','server/arena_state.lua','server/interactions.lua','client/materials.lua','client/lighting.lua','client/wet_surface.lua','client/arenas.lua','client/lod.lua','client/interactions.lua','client/main.lua']
xml=['<meta>','  <info author="ProjectSquidGenesis" name="ProjectSquidGenesis" type="map" version="0.6.0" />','  <min_mta_version client="1.6.0" server="1.6.0" />']
for f in files:xml.append(f'  <script src="{f}" type="{f.split("/")[0]}" />')
for folder in ('models','collisions','textures','shaders'):
    for f in sorted((ROOT/folder).rglob('*')):
        if f.is_file():xml.append(f'  <file src="{f.relative_to(ROOT).as_posix()}" />')
xml+=[f'  <export function="{name}" type="server" />' for name in ['setPanelState','getPanelState','getInteractionState','getSlotOccupant']]+['</meta>'];(ROOT/'meta.xml').write_text('\n'.join(xml)+'\n')
